const asyncTicks = {
  [Symbol.asyncIterator]() {
    let step = 1;
    return {
      async next() {
        if (step > 3) return { value: undefined, done: true };
        await new Promise((r) => setTimeout(r, 10));
        return { value: step++, done: false };
      },
    };
  },
};

