type HasUrl = { hasUrl: true };
type HasMethod = { hasMethod: true };

class RequestBuilder<State = {}> {
  private cfg: { url?: string; method?: string } = {};

  url(u: string): RequestBuilder<State & HasUrl> {
    this.cfg.url = u;
    return this as unknown as RequestBuilder<State & HasUrl>;
  }
  method(m: "GET" | "POST"): RequestBuilder<State & HasMethod> {
    this.cfg.method = m;
    return this as unknown as RequestBuilder<State & HasMethod>;
