from functools import wraps

def retry(times: int = 3):
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            for attempt in range(times):
                try:
                    return func(*args, **kwargs)
                except Exception as exc:
                    if attempt == times - 1:
                        raise exc
        return wrapper
    return decorator

