import 'dart:collection';

class CountDown extends IterableBase<int> {
  final int start;
  CountDown(this.start);

  @override
  Iterator<int> get iterator => _CountDownIterator(start);
}

class _CountDownIterator implements Iterator<int> {
  int _next;
  int _current = 0;
  _CountDownIterator(this._next);

  @override
  int get current => _current;

  @override
  bool moveNext() {
    if (_next <= 0) return false;
    _current = _next--;
    return true;
  }
}

void main() {
  print(CountDown(4).toList()); // [4, 3, 2, 1]
}

