import 'dart:isolate';

void workerEntry(SendPort mainSendPort) {
  final workerReceive = ReceivePort();
  mainSendPort.send(workerReceive.sendPort);

  workerReceive.listen((message) {
    if (message is (int, SendPort)) {
      final (value, replyTo) = message;
      replyTo.send(value * value);
    } else if (message == 'close') {
      workerReceive.close();
    }
  });
}

Future<void> main() async {
  final initPort = ReceivePort();
  await Isolate.spawn(workerEntry, initPort.sendPort);
  final workerPort = await initPort.first as SendPort;

  final replyPort = ReceivePort();
  workerPort.send((12, replyPort.sendPort));
  print('Square: ${await replyPort.first}');
  workerPort.send('close');
}

import 'dart:async';
import 'dart:isolate';

class SquareWorker {
  final SendPort _commands;
  final ReceivePort _responses;
  final Map<int, Completer<int>> _pending = {};
  int _nextId = 0;

  SquareWorker._(this._commands, this._responses) {
    _responses.listen((msg) {
      final (int id, int result) = msg as (int, int);
      _pending.remove(id)?.complete(result);
    });
  }

  static Future<SquareWorker> spawn() async {
    final init = ReceivePort();
    await Isolate.spawn(_entry, init.sendPort);
    final commands = await init.first as SendPort;
    final responses = ReceivePort();
    commands.send(responses.sendPort);
    return SquareWorker._(commands, responses);
  }

  static void _entry(SendPort initPort) {
    final inbox = ReceivePort();
    initPort.send(inbox.sendPort);
    SendPort? replyPort;
    inbox.listen((msg) {
      if (msg is SendPort) {
        replyPort = msg;
      } else if (msg is (int, int)) {
        final (id, val) = msg;
        replyPort?.send((id, val * val));
      } else if (msg == null) {
        inbox.close();
      }
    });
  }

  Future<int> square(int n) {
    final id = _nextId++;
    final completer = Completer<int>();
    _pending[id] = completer;
    _commands.send((id, n));
    return completer.future;
  }

  void close() {
    _commands.send(null);
    _responses.close();
  }
}

Future<void> main() async {
  final worker = await SquareWorker.spawn();
  print(await (worker.square(7), worker.square(9)).wait);
  worker.close();
}

