int cmpInt(const void *pa, const void *pb) {
    int a = *(const int *)pa;
    int b = *(const int *)pb;
    return (a > b) - (a < b);
}

int main(void) {
    int nums[] = {42, 7, 19, -3, 15};
    size_t n = sizeof(nums) / sizeof(nums[0]);
    qsort(nums, n, sizeof(int), cmpInt);
    for (size_t i = 0; i < n; i++) printf("%d ", nums[i]);
    printf("\n");
    return 0;
}

