typedef struct { int *data; size_t len, cap; } IntVec;

int vecPush(IntVec *v, int val) {
    if (v->len == v->cap) {
        size_t newCap = v->cap ? v->cap * 2 : 4;
        int *tmp = realloc(v->data, newCap * sizeof(*tmp));
        if (!tmp) return -1;
        v->data = tmp;
        v->cap = newCap;
    }
    v->data[v->len++] = val;
    return 0;
}

int main(void) {
    IntVec v = {0};
    for (int i = 0; i < 6; i++) vecPush(&v, i * 5);
    printf("len=%zu cap=%zu last=%d\n", v.len, v.cap, v.data[v.len - 1]);
    free(v.data);
    return 0;
}

