#include <stdio.h>
#include <stdbool.h>

#define CAP 4
typedef struct { int buf[CAP]; size_t head, tail, count; } Ring;

bool ringPush(Ring *r, int v) {
    if (r->count == CAP) return false;
    r->buf[r->tail] = v;
    r->tail = (r->tail + 1) % CAP;
    r->count++;
    return true;
}

bool ringPop(Ring *r, int *out) {
    if (r->count == 0) return false;
    *out = r->buf[r->head];
    r->head = (r->head + 1) % CAP;
    r->count--;
    return true;
}

int main(void) {
    Ring r = {0}; int x = 0;
    ringPush(&r, 11); ringPush(&r, 22);
    if (ringPop(&r, &x)) printf("Popped: %d\n", x);
    return 0;
}

