typedef struct { int items[16]; int top; } Stack;

bool push(Stack *s, int v) {
    if (s->top >= 16) return false;
    s->items[s->top++] = v;
    return true;
}

bool pop(Stack *s, int *out) {
    if (s->top <= 0) return false;
    *out = s->items[--s->top];
    return true;
}

int main(void) {
    Stack s = { .top = 0 }; int v = 0;
    push(&s, 100); push(&s, 200);
    while (pop(&s, &v)) printf("%d ", v);
    printf("\n");
    return 0;
}

