static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
static int sharedSum = 0;

void *incTask(void *arg) {
    (void)arg;
    for (int i = 0; i < 1000; i++) {
        pthread_mutex_lock(&lock);
        sharedSum++;
        pthread_mutex_unlock(&lock);
    }
    return NULL;
}

int main(void) {
    pthread_t t1, t2;
    pthread_create(&t1, NULL, incTask, NULL);
    pthread_create(&t2, NULL, incTask, NULL);
    pthread_join(t1, NULL); pthread_join(t2, NULL);
    printf("sharedSum = %d\n", sharedSum);
    return 0;
}

#include <stdio.h>
#include <pthread.h>

static pthread_mutex_t mtx = PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t cv = PTHREAD_COND_INITIALIZER;
static int ready = 0;

void *producer(void *arg) {
    (void)arg;
    pthread_mutex_lock(&mtx);
    ready = 1;
    pthread_cond_signal(&cv);
    pthread_mutex_unlock(&mtx);
    return NULL;
}

int main(void) {
    pthread_t p;
    pthread_create(&p, NULL, producer, NULL);
    pthread_mutex_lock(&mtx);
    while (!ready) pthread_cond_wait(&cv, &mtx);
    printf("Consumed signal!\n");
    pthread_mutex_unlock(&mtx);
    pthread_join(p, NULL);
    return 0;
}

