import { useState } from "react";

export function EditableRows() {
  const [rows, setRows] = useState([
    { id: "r1", label: "First" },
    { id: "r2", label: "Second" },
  ]);

  const prepend = () =>
    setRows((prev) => [{ id: crypto.randomUUID(), label: "New" }, ...prev]);

  return (
