export function ProfileEditor() {
  const [profile, setProfile] = useState({
    name: "Sara",
    address: { city: "Cairo" },
  });

  const moveToAlex = () => {
    setProfile((prev) => ({
      ...prev,
      address: { ...prev.address, city: "Alexandria" },
    }));
  };

  return <button onClick={moveToAlex}>{profile.name} — {profile.address.city}</button>;
