import { useState } from "react";

export function TagManager() {
  const [tags, setTags] = useState(["react", "ts"]);

  const addTag = (tag: string) => setTags((prev) => [...prev, tag]);
  const removeTag = (target: string) =>
    setTags((prev) => prev.filter((t) => t !== target));

  return (
    <div>
      <button onClick={() => addTag("nextjs")}>Add Next.js</button>
      {tags.map((t) => (
        <button key={t} onClick={() => removeTag(t)}>{t} ×</button>
      ))}
    </div>
  );
}

