export function ConcurrentFilter({ records }: { records: string[] }) {
  const [input, setInput] = useState("");
  const [filter, setFilter] = useState("");
  const [, startTransition] = useTransition();

  const onInput = (val: string) => {
    setInput(val); // Urgent
    startTransition(() => setFilter(val)); // Interruptible
  };

  const matches = records.filter((r) => r.includes(filter));
