export function SimpleVirtualList({ items, rowHeight = 36, height = 180 }: {
  items: string[];
  rowHeight?: number;
  height?: number;
}) {
  const [scrollTop, setScrollTop] = useState(0);
  const start = Math.floor(scrollTop / rowHeight);
  const visibleCount = Math.ceil(height / rowHeight) + 2;
  const slice = items.slice(start, start + visibleCount);

  return (
    <div style={{ height, overflowY: "auto" }} onScroll={(e) => setScrollTop(e.currentTarget.scrollTop)}>
      <div style={{ height: items.length * rowHeight, position: "relative" }}>
        {slice.map((item, idx) => (
          <div key={start + idx} style={{ position: "absolute", top: (start + idx) * rowHeight, height: rowHeight }}>
            {item}
          </div>
        ))}
      </div>
    </div>
  );
}

