"use client";
import { useOptimistic } from "react";

export function TodoOptimisticList({
  items,
  addAction,
}: {
  items: string[];
  addAction: (title: string) => Promise<void>;
}) {
  const [optimistic, addOptimistic] = useOptimistic(items, (s, next: string) => [...s, next]);

  async function submit(fd: FormData) {
    const title = String(fd.get("title") ?? "");
    addOptimistic(title);
    await addAction(title);
  }

  return (
    <form action={submit}>
      <input name="title" required />
      <button type="submit">Add</button>
      <ul>{optimistic.map((t, i) => <li key={i}>{t}</li>)}</ul>
    </form>
  );
}

