import 'dart:convert';
import 'package:http/http.dart' as http;

Future<Map<String, dynamic>> fetchUserProfile(http.Client client) async {
  final res = await client
      .get(Uri.https('api.example.com', '/profile'))
      .timeout(const Duration(seconds: 10));
  if (res.statusCode < 200 || res.statusCode >= 300) {
    throw Exception('HTTP error ${res.statusCode}');
  }
  return jsonDecode(res.body) as Map<String, dynamic>;
}

import 'package:dio/dio.dart';

Dio createApiClient(String token) {
  final dio = Dio(BaseOptions(
    baseUrl: 'https://api.example.com',
    connectTimeout: const Duration(seconds: 10),
    receiveTimeout: const Duration(seconds: 10),
  ));
  dio.interceptors.add(InterceptorsWrapper(
    onRequest: (options, handler) {
      options.headers['Authorization'] = 'Bearer $token';
      handler.next(options);
    },
  ));
  return dio;
}

Future<Response<dynamic>> loadItems(Dio dio, CancelToken cancelToken) {
  return dio.get('/items', cancelToken: cancelToken);
}

