}
/* Because utilities comes after components, class="btn-primary bg-red-600" wins! */

/* Tailwind v4 uses :where() in variant selectors (like space-y, dark, group)
   to keep specificity low so simple utilities still override them cleanly. */
.space-y-4 > :not(:last-child) { margin-bottom: 1rem; }

@layer components {
  .btn-badge {
    @apply inline-flex items-center rounded-full px-2.5 py-0.5 text-xs font-medium;
  }
}

