import type { LoaderFunctionArgs } from "react-router";

export async function projectLoader({ params, request }: LoaderFunctionArgs) {
  const projectId = params.projectId;
  if (!projectId) {
    throw new Response("Missing project ID", { status: 400 });
  }

  const res = await fetch(`/api/projects/${projectId}`, {
    signal: request.signal,
    headers: { Accept: "application/json" },
  });

  if (!res.ok) {
    throw new Response("Project not found", { status: res.status });
  }
  return res.json();
}

import type { LoaderFunctionArgs } from "react-router";
import { useLoaderData } from "react-router";

export async function catalogLoader({ request }: LoaderFunctionArgs) {
  const url = new URL(request.url);
  const query = url.searchParams.get("q") ?? "";
  const page = Number(url.searchParams.get("page") ?? "1");

  const res = await fetch(`/api/catalog?q=${encodeURIComponent(query)}&page=${page}`);
  return { items: await res.json(), query, page };
}

export function CatalogPage() {
  const { query, page } = useLoaderData<typeof catalogLoader>();
  return <p>Showing page {page} for "{query}"</p>;
}

import { redirect, type LoaderFunctionArgs } from "react-router";

export async function protectedLoader({ request }: LoaderFunctionArgs) {
  const session = await fetch("/api/session").then((r) => (r.ok ? r.json() : null));

  if (!session) {
    const pathname = new URL(request.url).pathname;
    throw redirect(`/login?redirectTo=${encodeURIComponent(pathname)}`);
  }

  return { user: session.user };
}

import { data, type LoaderFunctionArgs } from "react-router";

export async function articleLoader({ params }: LoaderFunctionArgs) {
  const article = await fetch(`/api/articles/${params.slug}`).then((r) =>
    r.ok ? r.json() : null
  );

  if (!article) {
    throw data({ message: "Article not found", slug: params.slug }, { status: 404 });
  }

  return data(article, {
    headers: { "Cache-Control": "public, max-age=60" },
  });
}

