import { useRef } from "react";
import { Form, useSubmit } from "react-router";

export function DebouncedSearchInput({ initialQuery }: { initialQuery: string }) {
  const submit = useSubmit();
  const timerRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  function handleSearchChange(form: HTMLFormElement | null, isFirstSearch: boolean) {
    if (timerRef.current) clearTimeout(timerRef.current);
    timerRef.current = setTimeout(() => {
      if (form) submit(form, { replace: !isFirstSearch });
    }, 250);
  }

  return (
    <Form method="get">
      <input
        name="q"
        defaultValue={initialQuery}
        onChange={(e) => handleSearchChange(e.currentTarget.form, initialQuery === "")}
        placeholder="Search..."
      />
    </Form>
  );
}

