import { createAppAsyncThunk } from "./appThunk";

export const submitOrder = createAppAsyncThunk<{ orderId: string }, { sku: string }>(
  "orders/submit",
  async (orderInput, { rejectWithValue }) => {
    const res = await fetch("/api/orders", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(orderInput),
    });

    if (!res.ok) {
      const body = await res.json();
      return rejectWithValue({ code: res.status, message: body.error });
    }
    return (await res.json()) as { orderId: string };
  }
);

import { useState } from "react";
import { useAppDispatch } from "./hooks";
import { submitOrder } from "./ordersThunks";

export function CheckoutButton({ sku }: { sku: string }) {
  const dispatch = useAppDispatch();
  const [errorMsg, setErrorMsg] = useState<string | null>(null);

  async function handleBuy() {
    setErrorMsg(null);
    try {
      const result = await dispatch(submitOrder({ sku })).unwrap();
      alert(`Order confirmed: ${result.orderId}`);
    } catch (rejectedErr: unknown) {
      const err = rejectedErr as { message?: string };
      setErrorMsg(err.message ?? "Order failed");
    }
  }

  return (
    <div>
      <button onClick={handleBuy}>Place Order</button>
      {errorMsg && <p className="text-red-500">{errorMsg}</p>}
    </div>
  );
}

