import { combineReducers, createAction, type UnknownAction } from "@reduxjs/toolkit";
import authReducer from "./authSlice";
import ordersReducer from "./ordersSlice";

export const logoutReset = createAction("auth/logoutReset");

const appReducer = combineReducers({
  auth: authReducer,
  orders: ordersReducer,
});

export function rootReducer(
  state: ReturnType<typeof appReducer> | undefined,
  action: UnknownAction
) {
  if (logoutReset.match(action)) {
    state = undefined; // Every slice falls back to its initialState!
  }
  return appReducer(state, action);
}

