import { createListenerMiddleware } from "@reduxjs/toolkit";
import { loginStarted, loginSucceeded, logout } from "./authSlice";

export const authListener = createListenerMiddleware();

authListener.startListening({
  actionCreator: loginStarted,
  effect: async (_action, listenerApi) => {
    // Pause until either loginSucceeded fires or 10s elapses
    const matched = await listenerApi.condition(
      (action) => loginSucceeded.match(action) || logout.match(action),
      10_000
    );
    if (matched) {
      console.log("Auth flow resolved before timeout");
    }
  },
});

