// Execution order for a single HTTP request:
// 1. Incoming Middleware (global -> module)
// 2. Guards (global -> controller -> route)
// 3. Interceptors BEFORE handler (global -> controller -> route)
// 4. Pipes (global -> controller -> route -> param)
// 5. Route Handler (Controller method)
// 6. Interceptors AFTER handler (route -> controller -> global)
// 7. Exception Filters (route -> controller -> global, if error thrown)
export const PIPELINE_ORDER = ['Middleware', 'Guards', 'Interceptors(pre)', 'Pipes', 'Handler', 'Interceptors(post)', 'Filters'];

