import { Injectable, UnauthorizedException } from '@nestjs/common';
import { JwtService } from '@nestjs/jwt';

@Injectable()
export class TokenService {
  constructor(private readonly jwt: JwtService) {}

  async issuePair(userId: string, role: string) {
    const [accessToken, refreshToken] = await Promise.all([
      this.jwt.signAsync({ sub: userId, role }, { expiresIn: '15m' }),
      this.jwt.signAsync({ sub: userId, typ: 'refresh' }, { expiresIn: '7d' }),
    ]);
    return { accessToken, refreshToken };
  }

  verifyRefresh(token: string) {
    const payload = this.jwt.verify<{ sub: string; typ: string }>(token);
    if (payload.typ !== 'refresh') throw new UnauthorizedException();
    return payload;
  }
}

