import { CanActivate, ExecutionContext, Injectable } from '@nestjs/common';

@Injectable()
export class MultiTransportAuthGuard implements CanActivate {
  canActivate(ctx: ExecutionContext): boolean {
    const type = ctx.getType<'http' | 'ws' | 'rpc'>();
    if (type === 'ws') {
      const client = ctx.switchToWs().getClient();
      return Boolean(client.handshake?.auth?.token);
    }
    if (type === 'rpc') {
      return Boolean(ctx.switchToRpc().getContext());
    }
    return Boolean(ctx.switchToHttp().getRequest().headers.authorization);
  }
}

