export async function authMiddleware(req, res, next) {
  try {
    const token = req.headers.authorization?.split(" ")[1];
    if (!token) return res.status(401).json({ message: "Unauthorized" });
    req.user = await verifyToken(token);
    next();
  } catch (error) {
    next(error);
  }
}

