  const socket = connectSocket();
  socket.on('ticket:updated', (ticket: Ticket) => {
    queryClient.setQueryData(['ticket', ticket.id], ticket);
    queryClient.invalidateQueries({ queryKey: ['tickets', 'list'] });
  });
  return () => socket.disconnect();
}, [queryClient]);

