export const ordersQueries = {
  all: () => ['orders'] as const,
  list: (filter: OrderFilter) =>
    queryOptions({
      queryKey: [...ordersQueries.all(), 'list', filter],
      queryFn: ({ signal }) => fetchOrders(filter, signal),
      staleTime: 60_000,
    }),
  detail: (id: string) =>
    queryOptions({
      queryKey: [...ordersQueries.all(), 'detail', id],
      queryFn: ({ signal }) => fetchOrder(id, signal),
    }),
};

